init_modules_watch_stub();
function initLLM(config) {
  return {
    async chat(messages) {
      const response = await fetch("https://api.groq.com/openai/v1/chat/completions", {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${config.apiKey}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          model: config.model,
          messages,
          temperature: 0.7,
          max_tokens: 2048
        })
      });
      if (!response.ok) {
        const err = await response.text();
        throw new Error(`Groq API error ${response.status}: ${err}`);
      }
      const data = await response.json();
      return data.choices?.[0]?.message?.content || "";
    }
  };
}
__name(initLLM, "initLLM");

// src/session.ts
init_modules_watch_stub();
var MAX_HISTORY = 20;
function initSessionStore(env) {
  const kv = env.SESSIONS;
  return {
    async get(userId) {
      if (!kv) return [];
      try {
        const raw = await kv.get(`session:${userId}`, "text");
        return raw ? JSON.parse(raw) : [];
      } catch {
        return [];
      }
    },
    async add(userId, message) {
      if (!kv) return;
      const history = await this.get(userId);
      history.push(message);
      const trimmed = history.slice(-MAX_HISTORY);
      await kv.put(`session:${userId}`, JSON.stringify(trimmed), {
        expirationTtl: 86400 * 7
      });
    },
    async clear(userId) {
      if (!kv) return;
      await kv.delete(`session:${userId}`);
    }
  };
}
__name(initSessionStore, "initSessionStore");

